verus! {

fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
    ensures
        // Result has exactly one more element than the input
        result.len() == c.len() + 1,
        // The first element is 0.0
        result.index(0) == 0.0,
        // For each input index i, result[i+1] == c[i]
        forall |i: usize| (i < c.len()) ==> result.index(i + 1) == c.index(i),
{
    let len = c.len();
    // Pre-allocate space for the new vector
    let mut res: Vec<f32> = Vec::with_capacity(len + 1);
    // Prefix the 0.0
    res.push(0.0);

    let mut i: usize = 0;
    // Copy each element of c in order
    while i < len
        invariant
            // The loop counter stays in range
            i <= len,
            // So far, res has exactly i+1 elements (the prefix plus i copied elements)
            res.len() == i + 1,
            // The first element remains 0.0
            res.index(0) == 0.0,
            // All elements up to i−1 have been correctly copied:
            // res[k+1] == c[k] for 0 <= k < i
            forall |k: usize| (k < i) ==> res.index(k + 1) == c.index(k),
        decreases len - i,
    {
        // Safe to index c at i because i < len
        let v = c.index(i);
        res.push(v);
        i = i + 1;
    }

    // At this point i == len, so res.len() == len+1 and res[1..] == c[0..]
    res
}

} // end verus!

